  <script>
    const tools = [
      {tag: "client-tool", text: "Vendég keresése e-mail alapján", icon: 'M17.25 6.75 22.5 12l-5.25 5.25m-10.5 0L1.5 12l5.25-5.25m7.5-3-4.5 16.5'},
