                    </svg>
                </div>
                <div class="flex flex-col space-y-0.5">
                    <span class="text-[10px] text-neutral-500 font-mono bg-white/10 px-1.5 py-0.5 rounded w-fit uppercase tracking-wide border border-white/5">${t.tag}</span>
                    <span class="text-zinc-300 block text-xs font-medium">${t.text}</span>
                </div>
            </div>`;
    });

    function updateUI(step) {
      const step1 = document.getElementById('step1');
      const chatInterface = document.getElementById('chat-interface');
      const statusContainer = document.getElementById('status-container');
      const planList = document.getElementById('plan-list');
      const evalContainer = document.getElementById('eval-container');
      const userThanks = document.getElementById('user-thanks');

      step1.style.opacity = (step === 1) ? "1" : "0";
      chatInterface.style.opacity = (step >= 2) ? "1" : "0";

      let statusHTML = '';
      if (step === 3) statusHTML = '<div class="absolute left-0 top-0 flex items-center gap-3 fade-in-up"><span class="text-zinc-400 text-[15px]">Rendben, egy pillanat, megkeresem a foglalást...</span></div>';
