                    <div><span class="text-[13px] font-medium transition-colors ${step >= p.trigger ? 'text-white' : 'text-neutral-500'}">${p.text}</span></div>
                </div>`;
      });

      evalContainer.innerHTML = '';
      evals.forEach(e => {
        if (step >= e.step) {
          evalContainer.innerHTML += `
