                        <div class="min-w-[280px] shrink-0 space-y-3 rounded-2xl border border-white/20 bg-black/90 backdrop-blur-md p-4 shadow-xl">
                            <div class="flex items-center gap-3">
                                <div class="flex size-8 items-center justify-center rounded-lg border border-white/10 bg-white/5">
                                    <svg class="w-4 h-4 text-zinc-100" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" d="${e.icon}"/></svg>
                                </div>
                                <div class="flex flex-col"><span class="text-[10px] text-neutral-500 font-mono uppercase tracking-wide">${e.tag}</span><span class="text-zinc-100 text-[13px] font-medium">${e.name}</span></div>
                            </div>
                            <div class="space-y-2 bg-white/5 rounded-lg p-2.5 border border-white/5">
                                <div class="flex justify-between text-[11px]"><span class="text-neutral-500 font-medium">Bemenet</span><span class="text-zinc-300 font-mono">${e.input}</span></div>
                                ${e.output ? `<div class="h-px bg-white/5 my-1"></div><div class="flex justify-between text-[11px]"><span class="text-neutral-500 font-medium">Kimenet</span><span class="text-blue-400 font-mono">${e.output}</span></div>` : ''}
                            </div>
                        </div>
                    </div>`;
        }
      });

      userThanks.style.opacity = (step >= 10) ? "1" : "0";
    }

    async function runAnimation() {
      const timings = [2000, 1000, 1000, 800, 800, 800, 800, 800, 800, 3000];
      while (true) {
        for (let i = 1; i <= 10; i++) {
          updateUI(i);
          await new Promise(r => setTimeout(r, timings[i - 1]));
        }
        updateUI(0);
        await new Promise(r => setTimeout(r, 500));
      }
    }

    runAnimation();
  </script>

</body>

</html>

